const string D="Assets/Scenes/Oasis/YachtPortAtlas";static Material mat;static MarinaExistingPropsDetail(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("MarinaExistingPropsDetail.request"))return;File.Delete("MarinaExistingPropsDetail.request");Run();}
static Texture2D Read(string path){var imp=(TextureImporter)AssetImporter.GetAtPath(path);imp.isReadable=true;imp.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Texture2D>(path);}
static void Pack(){string path=D+"/Shared Yacht Yard Atlas.png";if(AssetDatabase.LoadAssetAtPath<Texture2D>(path).height==1536)return;File.Copy(path,"FinalEnvironmentRoadBackup/BeforeWorkingMarina/Atlas Before Existing Props.png",true);var old=Read(path);var prop=Read("Assets/Scenes/Oasis/3D/Texture/Roads Props/Roads-Props.jpg");var output=new Texture2D(2048,1536,TextureFormat.RGBA32,false);var pixels=Enumerable.Repeat(Color.white,2048*1536).ToArray();var previous=old.GetPixels();for(int y=0;y<1024;y++)Array.Copy(previous,y*2048,pixels,(y+512)*2048,2048);for(int y=0;y<512;y++)for(int x=0;x<512;x++)pixels[y*2048+x]=prop.GetPixelBilinear((x+.5f)/512,(y+.5f)/512);output.SetPixels(pixels);output.Apply();File.WriteAllBytes(path,output.EncodeToPNG());UnityEngine.Object.DestroyImmediate(output);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceUpdate);var imp=(TextureImporter)AssetImporter.GetAtPath(path);imp.isReadable=false;imp.mipmapEnabled=true;imp.streamingMipmaps=true;imp.npotScale=TextureImporterNPOTScale.None;foreach(string platform in new[]{"Android","iPhone"})imp.SetPlatformTextureSettings(new TextureImporterPlatformSettings{name=platform,overridden=true,maxTextureSize=2048,format=TextureImporterFormat.ASTC_6x6,compressionQuality=90});imp.SaveAndReimport();}
static GameObject ConvertProp(MeshFilter f,string name){var data=typeof(FinalPNGCityDetails).GetMethod("Read",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{f.sharedMesh});var p=((Vector3[])data.GetType().GetField("p").GetValue(data)).Select(f.transform.TransformPoint).ToArray();var n=((Vector3[])data.GetType().GetField("normal").GetValue(data)).Select(v=>f.transform.TransformDirection(v).normalized).ToArray();var uv=((Vector2[][])data.GetType().GetField("uv").GetValue(data))[0];var ids=(int[])data.GetType().GetField("ids").GetValue(data);var low=p.Aggregate(Vector3.Min);var hi=p.Aggregate(Vector3.Max);var origin=new Vector3((low.x+hi.x)*.5f,low.y,(low.z+hi.z)*.5f);var mesh=new Mesh{name=name+" original geometry shared atlas",indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.vertices=p.Select(v=>v-origin).ToArray();mesh.normals=n;mesh.uv=uv;mesh.triangles=ids;mesh.SetUVs(1,p.Select(v=>new Vector4(8,0,0,1)).ToList());mesh.SetColors(p.Select(v=>Color.white).ToList());mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,D+"/Meshes/"+name+" Original Prop.asset");var g=new GameObject(name);g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=mat;var lod=g.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.014f,new[]{g.GetComponent<MeshRenderer>()})});lod.RecalculateBounds();PrefabUtility.SaveAsPrefabAsset(g,D+"/"+name+" Shared Atlas.prefab");return g;}
static Dictionary<char,string[]> font=new Dictionary<char,string[]>{['A']=new[]{"01110","10001","11111","10001","10001"},['C']=new[]{"01111","10000","10000","10000","01111"},['E']=new[]{"11111","10000","11110","10000","11111"},['H']=new[]{"10001","10001","11111","10001","10001"},['I']=new[]{"11111","00100","00100","00100","11111"},['K']=new[]{"10001","10010","11100","10010","10001"},['L']=new[]{"10000","10000","10000","10000","11111"},['M']=new[]{"10001","11011","10101","10001","10001"},['N']=new[]{"10001","11001","10101","10011","10001"},['O']=new[]{"01110","10001","10001","10001","01110"},['P']=new[]{"11110","10001","11110","10000","10000"},['R']=new[]{"11110","10001","11110","10010","10001"},['S']=new[]{"01111","10000","01110","00001","11110"},['T']=new[]{"11111","00100","00100","00100","00100"},['Y']=new[]{"10001","01010","00100","00100","00100"}};
static void Text(ReferenceWorkingMarinaGeo g,string text,Vector3 center,float pixel,Color color,bool wall=false){float start=-text.Length*6*pixel*.5f;for(int letter=0;letter<text.Length;letter++){if(!font.TryGetValue(text[letter],out var rows))continue;for(int row=0;row<5;row++)for(int col=0;col<5;col++)if(rows[row][col]=='1'){var a=center+Vector3.right*(start+(letter*6+col)*pixel)+(wall?Vector3.up:Vector3.forward)*(4-row)*pixel;var b=a+Vector3.right*pixel*.9f;var c=a+(wall?Vector3.up:Vector3.forward)*pixel*.9f;var d=b+(wall?Vector3.up:Vector3.forward)*pixel*.9f;g.Tri(a,c,b,-1,color);g.Tri(b,c,d,-1,color);}}}
class ReferenceWorkingMarinaGeo{public List<Vector3> p=new List<Vector3>();public List<Color> colors=new List<Color>();public List<int> ids=new List<int>();public void Tri(Vector3 a,Vector3 b,Vector3 c,int tile,Color color){int n=p.Count;p.AddRange(new[]{a,b,c});colors.AddRange(new[]{color,color,color});ids.AddRange(new[]{n,n+1,n+2});}public void Rect(Vector3 center,float width,float depth,Color color){var a=center+new Vector3(-width/2,0,-depth/2);var b=a+Vector3.right*width;var c=a+Vector3.forward*depth;var d=c+Vector3.right*width;Tri(a,c,b,-1,color);Tri(b,c,d,-1,color);}public Mesh Save(string name){var mesh=new Mesh{name=name,indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.SetVertices(p);mesh.SetColors(colors);mesh.SetUVs(0,p.Select(v=>Vector2.zero).ToList());mesh.SetUVs(1,p.Select(v=>new Vector4(-1,0,0,0)).ToList());mesh.SetTriangles(ids,0);mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,D+"/Meshes/"+name+".asset");return mesh;}}
static GameObject Place(GameObject prefab,Transform root,Vector3 pos){var g=(GameObject)PrefabUtility.InstantiatePrefab(prefab,root);g.transform.localPosition=pos;return g;}
static void Run(){try{var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");Pack();mat=AssetDatabase.LoadAssetAtPath<Material>(D+"/Shared Yacht Yard Atlas.mat");mat.SetTexture("_Atlas",AssetDatabase.LoadAssetAtPath<Texture2D>(D+"/Shared Yacht Yard Atlas.png"));EditorUtility.SetDirty(mat);var yard=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads").GetComponentsInChildren<MeshFilter>().Single(f=>f.name=="Yatch_Port");var candidates=yard.transform.Cast<Transform>().Where(t=>t.GetComponentsInChildren<MeshFilter>().Any(f=>f.name=="Harbour operations office")).ToArray();var root=candidates.First();foreach(var extra in candidates.Skip(1))UnityEngine.Object.DestroyImmediate(extra.gameObject);int removed=0;foreach(var child in root.Cast<Transform>().ToArray())if(child.name.Contains("Yacht")||child.name.Contains("yacht")||child.name.Contains("Helicopter")||child.name.Contains("helicopter")||child.name.Contains("Forklifts")){if(child.name=="Left helicopter landing pad"||child.name=="Three yacht berth fingers")continue;UnityEngine.Object.DestroyImmediate(child.gameObject);removed++;}float y=yard.sharedMesh.vertices.Max(v=>v.y),width=yard.sharedMesh.bounds.size.x,depth=yard.sharedMesh.bounds.size.z;var lampSource=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).First(f=>f.name.StartsWith("metal street props low poly.012"));foreach(var pair in new[]{Tuple.Create(lampSource,"Existing Garden Lamp"),Tuple.Create(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Scenes/Oasis/3D/Prefeb/bollard.prefab").GetComponentInChildren<MeshFilter>(),"Existing Striped Road Bollard"),Tuple.Create(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Scenes/Oasis/3D/Prefeb/cones.prefab").GetComponentInChildren<MeshFilter>(),"Existing Traffic Cone"),Tuple.Create(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Scenes/Oasis/3D/Prefeb/barricade.prefab").GetComponentInChildren<MeshFilter>(),"Existing Yellow Barrier")}){var g=ConvertProp(pair.Item1,pair.Item2);UnityEngine.Object.DestroyImmediate(g);}var lamp=AssetDatabase.LoadAssetAtPath<GameObject>(D+"/Existing Garden Lamp Shared Atlas.prefab");var bollard=AssetDatabase.LoadAssetAtPath<GameObject>(D+"/Existing Striped Road Bollard Shared Atlas.prefab");var cone=AssetDatabase.LoadAssetAtPath<GameObject>(D+"/Existing Traffic Cone Shared Atlas.prefab");var barrier=AssetDatabase.LoadAssetAtPath<GameObject>(D+"/Existing Yellow Barrier Shared Atlas.prefab");for(int i=0;i<6;i++)Place(lamp,root,new Vector3(-93+i*36,y,-depth/2+3));for(int i=0;i<4;i++)Place(lamp,root,new Vector3(-35+i*40,y,depth/2-3));for(float x=-width/2+7;x<width/2-4;x+=7)Place(bollard,root,new Vector3(x,y,-depth/2+1));for(int i=0;i<8;i++)Place(cone,root,new Vector3(-95+(i%4)*16,y,i<4?-26:26));for(int i=0;i<4;i++)Place(barrier,root,new Vector3(12+i*20,y,depth/2-2));
