PrefabUtility.SaveAsPrefabAsset(root.gameObject,D+"/Reference Working Marina Features.prefab");var standalone=UnityEngine.Object.Instantiate(yard.gameObject);standalone.name="Yatch_Port reference detail no vehicles";PrefabUtility.SaveAsPrefabAsset(standalone,D+"/Yatch_Port Reference Working Marina.prefab");UnityEngine.Object.DestroyImmediate(standalone);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var center=yard.transform.TransformPoint(new Vector3(0,y,0));typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{scene,center+yard.transform.TransformDirection(new Vector3(0,90,-115)),center,"Marina-Existing-Props-No-Vehicles"});File.WriteAllText("FinalEnvironmentRoadReview/MarinaExistingPropsReport.txt","SUCCESS removed vehicle groups="+removed+"; exact existing garden lamp/road bollard/cone/barrier meshes repacked using original props texture into same 2048x1536 atlas; 10 garden lamps, perimeter road bollards, cones and barriers; office/cargo retained; reference loading boxes, crossing, arrows, KEEP CLEAR, YACHTS ONLY and MARINA CONTROL markings; shared material/prefabs retained; shader errors="+ShaderUtil.GetShaderMessages(mat.shader).Count(m=>m.severity.ToString()=="Error"));}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/MarinaExistingPropsReport.txt","FAILED "+e);Debug.LogException(e);}}
